 const node=el('months'),w=Math.max(260,node.clientWidth),h=250,left=54,right=22,top=30,bottom=35,values=monthly(s,c),max=Math.max(.1,...values)*1.15,x=i=>left+i*(w-left-right)/11,sy=v=>h-bottom-v/max*(h-top-bottom);
